import React from 'react';
import './Footer.css';

const Footer = () => {
  const links = {
    'About Qatar Airways': ['About us', 'News', 'Careers', 'Investor relations', 'Sustainability'],
    'Help': ['FAQs', 'Contact us', 'Feedback', 'Travel advisories', 'Baggage information'],
    'Explore': ['Destinations', 'Offers & promotions', 'Qatar Duty Free', 'Cargo', 'Holidays'],
    'Privilege Club': ['About Privilege Club', 'Earn Avios', 'Spend Avios', 'Partners', 'Shop'],
  };

  return (
    <footer className="footer">
      <div className="footer-main">
        <div className="footer-logo">
          <div className="f-logo-icon">✦</div>
          <div>
            <div className="f-qatar">QATAR</div>
            <div className="f-airways">AIRWAYS</div>
          </div>
        </div>

        <div className="footer-links-grid">
          {Object.entries(links).map(([category, items]) => (
            <div key={category} className="footer-col">
              <h4>{category}</h4>
              <ul>
                {items.map((item) => (
                  <li key={item}><a href="#">{item}</a></li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>

      <div className="footer-bottom">
        <div className="social-links">
          <a href="#" className="social-btn">f</a>
          <a href="#" className="social-btn">𝕏</a>
          <a href="#" className="social-btn">in</a>
          <a href="#" className="social-btn">▶</a>
          <a href="#" className="social-btn">📷</a>
        </div>
        <div className="footer-legal">
          <span>© 2026 Qatar Airways. All rights reserved.</span>
          <a href="#">Privacy Policy</a>
          <a href="#">Terms & Conditions</a>
          <a href="#">Cookie Policy</a>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
